export const homeClearance=(x,z)=>Math.abs(z-streamZ(x))<3&&x>B.stream.minX-1&&x<B.stream.maxX+1||Math.abs(x-HOF.barn.x)<HOF.barn.w/2+.6&&Math.abs(z-HOF.barn.z)<HOF.barn.d/2+.6||Object.values(HOF.fields).some(f=>f.w&&Math.abs(x-f.x)<f.w/2+.5&&Math.abs(z-f.z)<f.d/2+.5)||x> -10&&x<0&&z< -12&&z> -23;
export function createHomeWorld(scene,height,colliders,interactive,animated,label,rockMaterial,buildingMaterials){
let seed=331;const rnd=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},groups={};const mat=(c,e={})=>new T.MeshStandardMaterial({color:c,roughness:.88,...e}),wood=mat('#927553'),stone=rockMaterial,gold=mat('#baa666'),green=mat('#5e8255');
function add(geo,m,p=scene){const o=new T.Mesh(geo,m);o.castShadow=true;o.receiveShadow=true;p.add(o);return o;}
function box(w,h,d,m,x,y,z,p=scene){const o=add(new T.BoxGeometry(w,h,d),m,p);o.position.set(x,y,z);return o;}
function ball(x,y,z,s,p=scene,m=stone){const o=add(new T.IcosahedronGeometry(1,2),m,p);o.position.set(x,y,z);o.scale.set(s,s*.65,s*.9);o.rotation.set(rnd(),rnd()*6,rnd());return o;}
function rod(a,b,r,m,p=scene){const u=new T.Vector3(...a),v=new T.Vector3(...b),d=v.clone().sub(u),o=add(new T.CylinderGeometry(r,r,d.length(),9),m,p);o.position.copy(u.add(v).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return o;}
const sourceZ=streamZ(B.stream.maxX);for(const[dx,dz,s]of[[.35,-.4,.9],[.65,.65,.72],[-.2,-1,.7]]){const r=ball(B.stream.maxX+dx,height(B.stream.maxX+dx,sourceZ+dz)+s*.3,sourceZ+dz,s);r.userData.kind='brook-spring-rock';colliders.push({type:'ellipse',x:B.stream.maxX+dx,z:sourceZ+dz,rx:s*.7,rz:s*.65});}
// A mountain stream with a single broad timber crossing on the village path.
const points=Array.from({length:Math.round((B.stream.maxX-B.stream.minX)*2)+1},(_,i)=>{const x=B.stream.minX+i*.5;return[x,streamZ(x)];}),verts=[],idx=[];let previousX=null;
for(let i=0;i<points.length;i++){const [x,z]=points[i];if(Math.abs(x-B.stream.bridgeX)<2.3){previousX=null;continue;}const k=verts.length/3;for(const side of [-1,1])verts.push(x,streamSurfaceHeight(x),z+side*(.74+.14*Math.sin(x*.62)+.065*Math.sin(x*1.31)));if(previousX!==null)idx.push(k-2,k-1,k,k-1,k+1,k);previousX=x;if(i%3===0){colliders.push({type:'ellipse',x,z,rx:.95,rz:1.1,passages:[{x:B.stream.bridgeX,z:streamZ(B.stream.bridgeX),w:5.6,d:8}]});for(const side of [-1,1])ball(x,height(x,z+side*1.4)+.03,z+side*1.4,.23+rnd()*.3);}}
const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(verts,3));geo.setIndex(idx);geo.computeVertexNormals();const water=add(geo,mat(P.stream,{roughness:.19,metalness:.06,transparent:true,opacity:.72,depthWrite:false,side:T.DoubleSide}));water.userData.kind='home-mountain-stream';
const currentMaterial=mat('#d3e7df',{transparent:true,opacity:.3,depthWrite:false,side:T.DoubleSide}),currents=new T.InstancedMesh(new T.PlaneGeometry(.3,.025),currentMaterial,58),flowPose=new T.Object3D();currents.userData.kind='stream-current';currents.castShadow=false;currents.receiveShadow=false;scene.add(currents);animated.push(t=>{for(let i=0;i<58;i++){const x=B.stream.minX+1+((i*.73+t*.28)%(B.stream.maxX-B.stream.minX-2)),z=streamZ(x)+Math.sin(i*5.7)*.65;flowPose.position.set(x,streamSurfaceHeight(x)+.015,z);flowPose.rotation.set(-Math.PI/2,0,-Math.atan(.24*Math.cos(x*.16)));flowPose.scale.set(Math.abs(x-B.stream.bridgeX)<2.4?0:.6+(i%5)*.16,1,1);flowPose.updateMatrix();currents.setMatrixAt(i,flowPose.matrix);}currents.instanceMatrix.needsUpdate=true;});
const bx=B.stream.bridgeX,bz=streamZ(bx);for(let i=0;i<14;i++)box(4.5,.1,.3,wood,bx,height(bx,bz)+.19,bz-2.1+i*.32);for(const side of[-1,1]){rod([bx+side*2.2,height(bx,bz)+.25,bz-2.2],[bx+side*2.2,height(bx,bz)+.85,bz-2.2],.06,wood);rod([bx+side*2.2,height(bx,bz)+.25,bz+2.2],[bx+side*2.2,height(bx,bz)+.85,bz+2.2],.06,wood);rod([bx+side*2.2,height(bx,bz)+.8,bz-2.2],[bx+side*2.2,height(bx,bz)+.8,bz+2.2],.045,wood);}
const fish=[];for(let i=0;i<9;i++){const g=new T.Group(),m=mat(i%2?'#71867a':'#b9b4a0',{roughness:.5});const b=add(new T.SphereGeometry(1,12,8),m,g);b.scale.set(.22,.055,.07);const tail=add(new T.ConeGeometry(.075,.12,3),m,g);tail.rotation.z=-Math.PI/2;tail.position.x=-.25;scene.add(g);g.userData.kind='stream-fish';fish.push(g);animated.push(t=>{const x=B.stream.minX+2+((t*.34+i*2.2)%(B.stream.maxX-B.stream.minX-4)),z=streamZ(x)+Math.sin(t*.7+i)*.35;g.position.set(x,streamSurfaceHeight(x)-.07,z);g.visible=Math.abs(x-B.stream.bridgeX)>2.4;g.rotation.y=-Math.atan(.24*Math.cos(x*.16));tail.rotation.y=Math.sin(t*7+i)*.4;});}
// The barn uses the same timber, masonry and shingle palette as the chalet.
const barn=buildHomesteadBarn(scene,height,colliders,buildingMaterials);barn.userData.navigationId='barn-entry';interactive.push({id:'barn-entry',x:HOF.barn.x,z:HOF.barn.z+4.3,range:1.5,name:'In den Stall gehen',barnDoor:true});interactive.push({id:'barn-supplies',x:HOF.barn.x,z:HOF.barn.z,range:1.5,name:'Leiheimer holen & Tiere versorgen',farmSupply:'barn'});
function cornField(id,cx,cz,w,d,n){const g=new T.Group();scene.add(g);g.userData.kind='estate-'+id;const soil=conformToTerrain({p:[cx-w/2,0,cz-d/2,cx+w/2,0,cz-d/2,cx-w/2,0,cz+d/2,cx+w/2,0,cz+d/2],uv:[0,0,1,0,0,1,1,1],ix:[0,2,1,1,2,3]},height,.025),soilGeo=new T.BufferGeometry();soilGeo.setAttribute('position',new T.Float32BufferAttribute(soil.p,3));soilGeo.setAttribute('uv',new T.Float32BufferAttribute(soil.uv,2));soilGeo.setIndex(soil.ix);soilGeo.computeVertexNormals();const soilMesh=add(soilGeo,mat('#938361'),g);soilMesh.userData.kind='cultivated-ground';g.add(createRipeWheat(height,{x:cx,z:cz,w,d,count:n,seed:id==='basic'?71:93},animated));groups[id]=g;return g;}
for(const[id,count]of[['basic',1440],['corn',1720]]){const f=HOF.fields[id];cornField(id,f.x,f.z,f.w,f.d,count);}
const cocoa=new T.Group();scene.add(cocoa);cocoa.userData.kind='estate-cocoa';const cx=-5,cz=-19;for(const x of[-8, -2])for(const z of[-22,-16])rod([x,height(x,z),z],[x,height(x,z)+2.5,z],.055,wood,cocoa);for(const z of[-22,-16]){rod([-8,height(-5,cz)+2.5,z],[-5,height(-5,cz)+3.4,z],.06,wood,cocoa);rod([-5,height(-5,cz)+3.4,z],[-2,height(-5,cz)+2.5,z],.06,wood,cocoa);}const glazing=mat('#b6d2c0',{transparent:true,opacity:.16,roughness:.25,side:T.DoubleSide,depthWrite:false});for(const side of[-1,1]){const pane=add(new T.PlaneGeometry(3.35,6),glazing,cocoa);pane.rotation.x=-Math.PI/2;pane.rotation.y=side*.29;pane.position.set(-5+side*1.5,height(-5,cz)+2.9,cz);}for(let i=0;i<8;i++){const x=-7+(i%2)*4,z=-21+Math.floor(i/2)*1.4,y=height(x,z);rod([x,y,z],[x,y+1.6,z],.05,wood,cocoa);for(let j=0;j<5;j++){const leaf=add(new T.SphereGeometry(1,10,7),green,cocoa);leaf.scale.set(.42,.055,.2);leaf.position.set(x+Math.sin(j*2.4)*.35,y+1.2+j*.1,z+Math.cos(j*2.4)*.3);leaf.rotation.z=Math.sin(j)*.4;}for(let j=0;j<2;j++){const pod=add(new T.SphereGeometry(1,10,8),mat('#a67c42'),cocoa);pod.scale.set(.1,.22,.1);pod.position.set(x+.1,y+.8+j*.35,z);}}groups.cocoa=cocoa;
for(const[id,h]of Object.entries(HARVESTS))interactive.push({id:'field-'+id,name:h.name+' · Anbau & Ernte',x:h.x,z:h.z,range:2,estateField:id});
// A bench faces the valley opening rather than the old sports arena.
for(const x of[-2.8,-.2])box(.11,.65,.11,wood,x,height(x,24)+.35,24);box(3.2,.14,.65,wood,-1.5,height(-1.5,24)+.72,24);box(3.2,.45,.1,wood,-1.5,height(-1.5,24)+1.05,23.7);colliders.push({x:-1.5,z:24,w:3.3,d:.8});interactive.push({id:'valley-view',name:'Den Blick ins Tal geniessen',x:-1.5,z:22.5,range:1.8,valleyView:true});
groups.corn.visible=false;groups.cocoa.visible=false;return{fish,groups,stream:water,barn,barnView(pos,active){const inside=inBarn(pos,active);barn.userData.inside=inside;for(const o of barn.userData.cutawayParts)o.visible=!inside;},sync(s){groups.basic.visible=!s.estate.built.corn;for(const k of['corn','cocoa'])groups[k].visible=!!s.estate.built[k];}};
}
